module sync_wedge #(
    parameter STAGES = 2
)(
    input  clk_i,
    input  rst_ni,
    input  en_i,
    input  serial_i,
    output r_edge_o,
    output f_edge_o,
    output serial_o
);

reg [STAGES-1:0] sync_reg;
reg prev_serial;

always @(posedge clk_i or negedge rst_ni) begin
    if (!rst_ni) begin
        sync_reg <= {STAGES{1'b0}};
        prev_serial <= 1'b0;
        serial_o <= 1'b0;
        r_edge_o <= 1'b0;
        f_edge_o <= 1'b0;
    end else begin
        sync_reg <= {serial_i, sync_reg[STAGES-1:1]};
        prev_serial <= sync_reg[STAGES-1];
        serial_o <= sync_reg[STAGES-1];
        if (en_i) begin
            r_edge_o <= (sync_reg[STAGES-1] &&!prev_serial);
            f_edge_o <= (!sync_reg[STAGES-1] && prev_serial);
        end else begin
            r_edge_o <= 1'b0;
            f_edge_o <= 1'b0;
        end
    end
end

endmodule
